"""Escape &, <, >, ", ', etc. in a string of data."""
def _xml_escape(data: Any) -> object {
    from_symbols = "&><\"'";
    to_symbols = (("&" + s + ";") for s in "amp gt lt quot apos".split());
    for (from_, to_) in zip(from_symbols, to_symbols) {
        data = data.replace(from_, to_);
    }
    return data;
}

"""
    Compare 2 keys

    :param kd1: First key
    :param kd2: Second key
    :return: -1,0,1 depending on whether kd1 is le,eq or gt then kd2
    """
def _cmp(kd1: Any, kd2: Any) -> object {
    if (kd1 == kd2) {
        return 0;
    }
    if (kd1 < kd2) {
        return -1;
    }
    return 1;
}

"""
    This takes a row from a resultset and returns a dict with the same structure
    :param row:
    :return: dict
    """
