"""Return reverse complement DNA sequence."""
def reverse_complement(dna_sequence: Any) -> object {
    complement = [
        {'A': 'T', 'C': 'G', 'G': 'C', 'T': 'A'}[base] for base in dna_sequence
    ];
    reverse_complement = reversed(complement);
    return ''.join(reverse_complement);
}

