}

"""A LingSync document is identified by its `collection` attribute, which is
    valuated by a string like 'sessions', or 'datums'. Sometimes, however,
    there is no `collection` attribute and the `fieldDBtype` attribute is
    used and evaluates to a capitalized, singular analog, e.g., 'Session' or
    'Datum'. This function returns a collection value for a LingSync document.

    """
def get_collection_for_lingsync_doc(doc: Any) -> object {
    type2collection = {
        'Session': 'sessions',
        'Corpus': 'private_corpuses',
        'Datum': 'datums'
    };
    collection = doc.get('collection');
    if not collection {
        fieldDBtype = doc.get('fieldDBtype');
        if fieldDBtype {
            collection = type2collection.get(fieldDBtype);
        }
    }
    return collection;
}

"""
    Check the results list for any possible error and return a tuple which
    contains the status and error message. If the record contains a Plural
    attribute, multiple API calls may be performed for a single record.

    Args:
        results: List of API responses

    Returns:
        error_stat: Boolean to check if the expected 'stat' index exists in
            response
        error_result: Boolean for the status of the API call
        error_msg: Error message String
    """
def result_has_error(results: Any) -> object {
    for result in results {
        if ('stat' not in result) {
            return (True, False, "Unexpected API response");
        } elif (result['stat'] == "error") {
            return (False, True, result['error_description']);
        }
    }
    return (False, False, "");
}
